import java.io.*;

public class Main {
    static final byte[] buf = new byte[1 << 16];
    static int bufLen = 0, bufPos = 0;
    static InputStream in = System.in;

    static int readByte() throws IOException {
        if (bufPos == bufLen) {
            bufLen = in.read(buf, 0, buf.length);
            bufPos = 0;
            if (bufLen <= 0) return -1;
        }
        return buf[bufPos++];
    }

    // Reads a non-negative integer as an unsigned 32-bit bit pattern.
    static int readInt() throws IOException {
        int c = readByte();
        while (c != -1 && c <= ' ') c = readByte();
        int x = 0;
        while (c > ' ') {
            x = x * 10 + (c - '0');
            c = readByte();
        }
        return x;
    }

    static final int[] count = new int[65536];

    // Two stable 16-bit radix passes sort a as unsigned 32-bit values (scratch has a's length).
    static void radixSort(int[] a, int[] scratch) {
        for (int shift = 0; shift <= 16; shift += 16) {
            java.util.Arrays.fill(count, 0);
            for (int v : a) count[(v >>> shift) & 65535]++;
            int sum = 0;
            for (int i = 0; i < 65536; i++) {
                int old = count[i];
                count[i] = sum;
                sum += old;
            }
            for (int v : a) scratch[count[(v >>> shift) & 65535]++] = v;
            System.arraycopy(scratch, 0, a, 0, a.length);
        }
    }

    public static void main(String[] args) throws IOException {
        int n = readInt();
        // Each [l, r] becomes toggle events at l and r + 1 (r + 1 may be 2^31: kept as unsigned bits).
        // ponytail: left and right events are sorted separately and merged, which needs 3n ints
        // instead of 4n so the largest case fits the JVM heap.
        int[] lefts = new int[n], rights = new int[n], scratch = new int[n];
        for (int i = 0; i < n; i++) {
            lefts[i] = readInt();
            rights[i] = readInt() + 1;
        }
        radixSort(lefts, scratch);
        radixSort(rights, scratch);
        // Walk the merged event order; events 2k and 2k+1 bound the on-segment [left, end).
        long answer = 0, left = 0;
        int i = 0, j = 0;
        for (int k = 0; k < 2 * n; k++) {
            long v;
            if (j == n || (i < n && Integer.compareUnsigned(lefts[i], rights[j]) <= 0)) v = Integer.toUnsignedLong(lefts[i++]);
            else v = Integer.toUnsignedLong(rights[j++]);
            if ((k & 1) == 0) left = v;
            else answer += (left + v - 1) * (v - left) / 2;
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	reader := bufio.NewReaderSize(os.Stdin, 1<<16)
	readInt := func() uint32 {
		c, err := reader.ReadByte()
		for err == nil && c <= ' ' {
			c, err = reader.ReadByte()
		}
		var x uint32
		for err == nil && c > ' ' {
			x = x*10 + uint32(c-'0')
			c, err = reader.ReadByte()
		}
		return x
	}
	n := int(readInt())
	// Each [l, r] becomes toggle events at l and r + 1.
	a := make([]uint32, 2*n)
	scratch := make([]uint32, 2*n)
	for i := 0; i < n; i++ {
		a[2*i] = readInt()
		a[2*i+1] = readInt() + 1
	}
	// Two stable 16-bit radix passes sort the events.
	count := make([]uint32, 65536)
	for _, shift := range []uint{0, 16} {
		clear(count)
		for _, v := range a {
			count[(v>>shift)&65535]++
		}
		var sum uint32
		for i, c := range count {
			count[i] = sum
			sum += c
		}
		for _, v := range a {
			k := (v >> shift) & 65535
			scratch[count[k]] = v
			count[k]++
		}
		a, scratch = scratch, a
	}
	// Events 2k and 2k+1 bound the on-segment [left, end); add its index sum.
	var answer uint64
	for i := 0; i < len(a); i += 2 {
		left, end := uint64(a[i]), uint64(a[i+1])
		answer += (left + end - 1) * (end - left) / 2
	}
	fmt.Println(answer)
}
